bool coplanar(const Tri &a, const Tri &b, Vec3 n) {
    int axis = 0;
    if (std::abs(n.y) > std::abs(n.x)) axis = 1;
    if (std::abs(n.z) > (axis == 0 ? std::abs(n.x) : std::abs(n.y))) axis = 2;
    Vec2 proj_a[3], proj_b[3];
    for (int i = 0; i < 3; ++i) {
        proj_a[i] = projected(a[i], axis);
        proj_b[i] = projected(b[i], axis);
    }
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            if (intersects2(proj_a[i], proj_a[(i + 1) % 3], proj_b[j], proj_b[(j + 1) % 3])) return true;
    return false;
}

