enum SessionVault {
    static func decode(from data: Data) -> [String: Any]? {
        // Step 1: Convert raw bytes into UTF-8 text.
        guard let text = String(data: data, encoding: .utf8) else {
            return nil // Not valid UTF-8.
        }
        // Step 2: Parse JSON using try? so errors become nil.
        guard let obj = try? JSONSerialization.jsonObject(with: Data(text.utf8)),
