sub parse_tokens {
    my ($buf, $len) = @_;
    my $cursor = 0;
    my @out;
    while ($cursor < $len) {
        my $tag = substr($buf, $cursor, 1);
        if ($tag eq 'H') {
            $cursor += 4;
            if (substr($buf, $cursor, 1) eq 'X') {
                $cursor += 2;
            }
        } elsif ($tag eq 'S') {
            $cursor -= 1;
        }
        push @out, $tag;
        $cursor += 1;
    }
    return \@out;
}

