/// A line-based manifest with required `name` and `port` fields.
/// Optional fields are `enabled`, `health_path`, and `health_interval_secs`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServiceManifest {
    pub name: String,
    pub port: u16,
    pub enabled: bool,
    pub health: HealthCheck,
}

/// HTTP health-check settings.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HealthCheck {
    pub path: String,
    pub interval_secs: u64,
}

/// An error encountered while parsing a service manifest.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ManifestError {
    Missing(&'static str),
    Duplicate(String),
    Invalid(String),
}

impl fmt::Display for ManifestError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Missing(key) => write!(f, "missing field: {key}"),
            Self::Duplicate(key) => write!(f, "duplicate field: {key}"),
            Self::Invalid(detail) => write!(f, "invalid manifest: {detail}"),
        }
    }
}

impl Error for ManifestError {}

fn set<T>(slot: &mut Option<T>, value: T, key: &str) -> Result<(), ManifestError> {
    if slot.is_some() {
        return Err(ManifestError::Duplicate(key.into()));
    }
    *slot = Some(value);
    Ok(())
}

impl FromStr for ServiceManifest {
    type Err = ManifestError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let (mut name, mut port) = (None, None);
        let (mut enabled, mut path, mut interval) = (None, None, None);
        for line in input.lines().map(str::trim) {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let (key, value) = line.split_once('=')
                .ok_or_else(|| ManifestError::Invalid(format!("expected key=value: {line}")))?;
            let (key, value) = (key.trim(), value.trim());
            let invalid = || ManifestError::Invalid(format!("{key}={value}"));
            match key {
                "name" => set(&mut name, value.to_owned(), key)?,
                "port" => set(&mut port, value.parse::<u16>().map_err(|_| invalid())?, key)?,
                "enabled" => set(&mut enabled, value.parse::<bool>().map_err(|_| invalid())?, key)?,
                "health_path" => set(&mut path, value.to_owned(), key)?,
                "health_interval_secs" => set(&mut interval, value.parse::<u64>().map_err(|_| invalid())?, key)?,
                _ => return Err(ManifestError::Invalid(format!("unknown field: {key}"))),
            }
        }
        let name = name.ok_or(ManifestError::Missing("name"))?;
        let port = port.ok_or(ManifestError::Missing("port"))?;
        let path = path.unwrap_or("/health".to_owned());
        let interval = interval.unwrap_or(30);
        if name.is_empty() { return Err(ManifestError::Invalid("empty name".into())); }
