/** Greedy, deterministic route-slot rescheduler for delayed trains. */
final class Scheduler {
    private Scheduler() {}

    static List<Model.PlanEntry> schedule(
            Model.Station station, Set<String> invalid, List<String> warnings) {
        List<Model.Train> trains = new ArrayList<>();
        for (Model.Train train : station.trains) {
            if (station.routes.containsKey(train.route)
                    && !invalid.contains(train.route)) {
                trains.add(train);
            }
        }
        trains.sort(Comparator.comparingInt(Model.Train::ready)
                .thenComparing(
                        Comparator.comparingInt((Model.Train train) -> train.priority)
                                .reversed())
                .thenComparing(train -> train.id));
        List<Model.PlanEntry> scheduled = new ArrayList<>();
        Map<String, Boolean> compatibility = new HashMap<>();
        int[] comparisons = {0};
        for (Model.Train train : trains) {
            int start = findSlot(
                    station, train, scheduled, compatibility, comparisons);
            if (start < 0) {
                warnings.add("reservation search limit reached; "
                        + train.id + " quarantined");
                continue;
            }
            scheduled.add(new Model.PlanEntry(train, start));
        }
        scheduled.sort(Comparator.comparingInt((Model.PlanEntry entry) -> entry.start)
                .thenComparing(
                        Comparator.comparingInt(
                                (Model.PlanEntry entry) -> entry.priority).reversed())
                .thenComparing(entry -> entry.train));
        return scheduled;
    }

    private static int findSlot(
            Model.Station station,
            Model.Train train,
            List<Model.PlanEntry> scheduled,
            Map<String, Boolean> compatibility,
            int[] comparisons) {
        Model.Route route = station.routes.get(train.route);
        int start = train.ready();
        int scans = 0;
        while (true) {
            int nextStart = advancePastConflicts(
                    station, route, train.duration, start, scheduled,
                    compatibility, comparisons);
            if (nextStart < 0 || ++scans > scheduled.size() + 1) {
                return -1;
            }
            if (nextStart == start) {
                return start;
            }
            start = nextStart;
        }
    }

    private static int advancePastConflicts(
            Model.Station station,
            Model.Route route,
            int duration,
            int start,
            List<Model.PlanEntry> scheduled,
            Map<String, Boolean> compatibility,
            int[] comparisons) {
        for (Model.PlanEntry reservation : scheduled) {
            if (++comparisons[0] > 2_000_000) {
                return -1;
            }
            Model.Route other = station.routes.get(reservation.route);
            String pair = Model.pair(route.id, other.id);
            boolean compatible = compatibility.computeIfAbsent(
                    pair, unused -> Safety.compatible(station, route, other));
            if (!compatible
                    && start < reservation.end
                    && reservation.start < start + duration) {
                start = reservation.end;
            }
        }
        return start;
    }
}

