const Polynomial = struct { quad: f64, linear: f64, constant: f64 };

fn bezierPolynomial(start: f64, control: f64, end: f64) Polynomial {
    return .{
        .quad = start - 2 * control + end,
        .linear = 2 * (control - start),
        .constant = start,
    };
}

fn evaluate(curve: Polynomial, param: f64) f64 {
    return (curve.quad * param + curve.linear) * param + curve.constant;
}

fn addCut(cuts: *[10]f64, count: *usize, param: f64) void {
    if (param <= 1e-10 or param >= 1 - 1e-10 or !std.math.isFinite(param)) return;
    for (cuts[0..count.*]) |prior| {
        if (@abs(prior - param) < 1e-10) return;
    }
    if (count.* < cuts.len) {
        cuts[count.*] = param;
        count.* += 1;
    }
}

fn roots(cuts: *[10]f64, count: *usize, polynomial: Polynomial, target: f64) void {
    const quad = polynomial.quad;
    const linear = polynomial.linear;
    const constant = polynomial.constant - target;
    if (@abs(quad) < 1e-12) {
        if (@abs(linear) > 1e-12) addCut(cuts, count, -constant / linear);
        return;
    }
    const discriminant = linear * linear - 4 * quad * constant;
    if (discriminant < 0) return;
    const root = @sqrt(discriminant);
    const factor = -0.5 * (linear + (if (linear >= 0) root else -root));
    if (@abs(factor) < 1e-15) {
        addCut(cuts, count, -linear / (2 * quad));
    } else {
        addCut(cuts, count, factor / quad);
        addCut(cuts, count, constant / factor);
    }
}

