                continue
            }
            val cost = current.cost + leg.leg.cost
            if (!cost.isFinite() || cost > options.maxCost) continue
            val hours = hoursBetween(case.procurement, leg.actualArrival)
            val arrivalViability = viability(hours, case.halfLifeHours)
            if (hours < 0 || hours > maxHours || arrivalViability < minViability) {
                continue
            }
            val next = Label(leg.actualTo, leg.actualArrival, cost, current.path + leg)
            val atLocation = labels.getOrPut(next.location) { mutableListOf() }
            if (atLocation.any { dominates(it, next) }) continue
            atLocation.removeAll { dominates(next, it) }
            atLocation.add(next)
            queue.add(next)
        }
    }
    if (results.isEmpty()) {
        routeWarnings.add("no itinerary satisfies the configured constraints")
    }
    val sorted = results.sortedWith(
        compareBy<Itinerary> { it.arrival }.thenBy { it.cost }
    )
    return SearchResult(sorted, routeWarnings)
}

fun plan(input: Input, options: Options): Plan {
    val match = assessMatch(input.case, options)
    val search = if (match.compatible) {
        findRoutes(input, options)
    } else {
        SearchResult(emptyList(), listOf("route search skipped because screening failed"))
    }
    val custodyAudit = auditCustody(input.custody, input.case)
    return Plan(
        input.case.id,
        match,
        search.itineraries,
        input.warnings + search.warnings,
        custodyAudit,
    )
}

